function r8Build(){
  const D=window.UP_DATA||[];
  let raw=D.map(d=>({stem:d[0],img:R8_IMG+d[0]+'.png',cat:d[1],mid:d[2],grp:d[3],name:d[4],finish:d[5],tags:(d[6]||'').split('|').filter(Boolean)}));
  // ── 코브라후드 정리: 중복(테이블/공백 중분류) 제거 ──
  // 260729 meeting: 하향식후드(코브라) has no sub-category — list products directly
  const seenCob={};
  raw=raw.filter(it=>{
    if(it.cat!=='코브라후드')return true;
    if(seenCob[it.name])return false;
    seenCob[it.name]=1;
    it.mid=''; it.grp=it.name;
    return true;
  });
  // ── 파이프 재분류 (260729 meeting / ref: 2.제품누끼_20260720 › 3.파이프) ──
  // before: mid = finish(스텐도금·스텐도장·스파이얼), grp = motion
  // after : mid = motion(양옆태엽·텐션·내부태엽·기타옵션), grp = finish
  raw.forEach(it=>{
    if(it.cat!=='파이프'||it.mid==='기타옵션')return;
    const finish=it.mid; it.mid=it.grp; it.grp=finish;
  });
  ITEMS=raw;
  // group into MODELS by cat|mid|grp.
  // 기타옵션 / LED 디자인등 buckets merge different-SHAPE products as if they were finishes;
  // for those, key by baseName (product name minus its finish) so distinct shapes become separate cards.
  const map={};
  ITEMS.forEach(it=>{
    const heterog=(it.mid==='기타옵션')||(it.cat==='LED조명'&&it.mid==='디자인등');
    const gkey=heterog?baseOf(it):it.grp;
    const k=it.cat+'|'+it.mid+'|'+gkey;
    if(!map[k]){map[k]={key:k,cat:it.cat,mid:it.mid,grp:gkey,items:[]};MODELS.push(map[k]);}
    map[k].items.push(it);
  });
  MODELS.forEach(m=>{m.rep=m.items[0];m.title=m.grp||m.mid||m.rep.name;});
  reorderGalB();
  R8_CATS.forEach(c=>byCatM[c]=MODELS.filter(m=>m.cat===c));
  renderHero(); renderCatNav(); renderBands(); renderCTA(); renderPartsTeaser(); applyTel();
}
// 260730) 갤럭시B 진열 순서 교정 — 원본 「2.제품누끼」 파일 번호(09→44) 흐름으로 재배열
//  304스텐 반후지(양옆→내부→파이프) → 304스텐 FVD(양옆→내부) → 스파이얼 반후지(양옆→내부) → 스파이얼 FVD(양옆→내부)
const GALB_ORDER=['304스텐-양옆태엽(반후지)','304스텐-내부태엽(반후지)','304스텐-90-100','304스텐-90-114',
 '304스텐-양옆태엽(FVD)','304스텐-내부태엽(FVD)','스파이얼-양옆태엽(반후지)','스파이얼-내부태엽(반후지)',
 '스파이얼-양옆태엽(FVD)','스파이얼-내부태엽(FVD)'];
function reorderGalB(){
  const slots=[], sub=[];
  MODELS.forEach((m,i)=>{if(m.cat==='갤럭시'&&m.mid==='갤럭시B'){slots.push(i);sub.push(m);}});
  if(!sub.length)return;
  const rank=g=>{const i=GALB_ORDER.indexOf(g);return i<0?99:i;};
  sub.sort((a,b)=>rank(a.grp)-rank(b.grp));   // Array#sort is stable → 동순위는 원본 순서 유지
  slots.forEach((p,j)=>{MODELS[p]=sub[j];});
}
