// scroll reveal — observe guide-page bands/teaser/cta
let revObs=null;
function r8SetupReveal(){
  if(!('IntersectionObserver'in window)){document.querySelectorAll('#v-main .reveal').forEach(el=>el.classList.add('in'));return;}
  if(revObs)revObs.disconnect();
  revObs=new IntersectionObserver((ents,obs)=>{
    ents.forEach(e=>{if(e.isIntersecting||e.boundingClientRect.top<0){e.target.classList.add('in');obs.unobserve(e.target);}});
  },{rootMargin:'0px 0px -10% 0px',threshold:.08});
  document.querySelectorAll('#v-main .reveal:not(.in)').forEach(el=>revObs.observe(el));
}
// part detail modal
function openPart(id){
  const p=R8_PARTS[id];if(!p)return;
  document.getElementById('pm-img').src=partSrc(id);
  document.getElementById('pm-img').alt=p.nm;
  // R3: extra shrink for low-res parts in the enlarged detail view
  document.querySelector('.pm-img').classList.toggle('lowres',PART_LOWRES.has(id));
  const grp=PART_GROUP_OF[id]||'부품 · 구성품';
  document.getElementById('pm-cat').textContent=grp;
  document.getElementById('pm-name').textContent=p.nm;
  const sp=document.getElementById('pm-sp');
  if(p.sp){sp.style.display='';sp.textContent='규격 '+p.sp;}else{sp.style.display='none';}
  document.getElementById('pm-desc').textContent=PART_GROUP_DESC[grp]||'유성에이스 정품 부품입니다.';
  const use=[...new Set(PART_USEDBY[id]||[])];
  const useEl=document.getElementById('pm-use'), useT=document.querySelector('.pm-use-t');
  if(use.length){useEl.innerHTML=use.map(c=>`<span>${c}</span>`).join('');useEl.style.display='';useT.style.display='';}
  else{useEl.style.display='none';useT.style.display='none';}
  document.getElementById('pmask').classList.add('on');document.body.style.overflow='hidden';
}
function closePart(){
  document.getElementById('pmask').classList.remove('on');
  if(!document.getElementById('mask').classList.contains('on'))document.body.style.overflow='';
}
